"""Private copied command/hash/census helpers for this boot gate only."""
import datetime
import hashlib
import json
import os
from pathlib import Path
import signal
import subprocess
import time

def sha(data):
    return hashlib.sha256(data).hexdigest()

def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()

def write_json(path, data):
    temporary = path.with_name(path.name + '.tmp')
    temporary.write_text(json.dumps(data, indent=2) + '\n')
    temporary.replace(path)

def aggregate(wt, source_map, source, expected_source):
    digest = hashlib.sha256()
    for entry in source_map:
        data = (wt / entry['path']).read_bytes()
        expected = expected_source if entry['path'] == source else entry['sha256']
        assert sha(data) == expected, f"Unexpected source bytes: {entry['path']}"
        digest.update(entry['path'].encode() + b'\0')
        digest.update(len(data).to_bytes(8, 'big'))
        digest.update(data)
    return digest.hexdigest()

def run_command(argv, cwd, env, folder, label, timeout):
    stdout = folder / (label + '.stdout.txt')
    stderr = folder / (label + '.stderr.txt')
    record = {'command': argv, 'cwd': str(cwd), 'started_at': now(),
              'timeout_seconds': timeout, 'stdout': stdout.name, 'stderr': stderr.name,
              'timeout_cleanup': [], 'process_group_scope': 'Owned process group only; descendants that create another session/group are fixture-owner responsibility.'}
    print(json.dumps({'event': 'start', 'label': label, 'folder': str(folder)}), flush=True)
    start = time.monotonic()
    process = None
    def group_alive():
        if process is None:
            return False
        try:
            os.killpg(process.pid, 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            record['group_probe_permission_errors'] = record.get('group_probe_permission_errors', 0) + 1
            return True
    def stop_owned():
        if process is None:
            return
        record['direct_status_before_cleanup'] = process.poll()
        record['owned_group_present_before_cleanup'] = group_alive()
        for sig in (signal.SIGTERM, signal.SIGKILL):
            if not group_alive() and process.poll() is not None:
                break
            try:
                os.killpg(process.pid, sig)
                record['timeout_cleanup'].append({'owned_process_group': process.pid, 'signal': sig.name})
            except ProcessLookupError:
                record['timeout_cleanup'].append({'owned_process_group': process.pid, 'signal': sig.name, 'already_gone': True})
            except PermissionError:
                record['timeout_cleanup'].append({'owned_process_group': process.pid, 'signal': sig.name, 'permission_error': True})
            deadline = time.monotonic() + 5
            while time.monotonic() < deadline:
                direct_done = process.poll() is not None
                if direct_done and not group_alive():
                    break
                time.sleep(0.01)
        process.wait(timeout=5)
        record['direct_wait_status'] = process.returncode
        record['owned_group_absent_after_cleanup'] = not group_alive()
        if not record['owned_group_absent_after_cleanup']:
            raise RuntimeError('Owned process group remains after bounded TERM/KILL cleanup')
    try:
        with stdout.open('wb') as out, stderr.open('wb') as err:
            if argv[0] == 'cargo':
                free = os.statvfs(folder)
                record['available_bytes_before_Cargo'] = free.f_bavail * free.f_frsize
                assert record['available_bytes_before_Cargo'] >= 5 * 1024**3, 'Insufficient disk before Cargo'
            process = subprocess.Popen(argv, cwd=cwd, env=env, stdout=out,
                                       stderr=err, start_new_session=True)
            record['owned_pid'] = record['owned_process_group'] = process.pid
            try:
                process.wait(timeout=timeout)
                record['timed_out'] = False
            except subprocess.TimeoutExpired:
                record['timed_out'] = True
            record['exit_code'] = process.returncode
            record['unexpected_residual_group_after_normal_exit'] = not record['timed_out'] and group_alive()
    except BaseException as error:
        record['controller_exception'] = repr(error)
        raise
    finally:
        try:
            stop_owned()
        except BaseException as cleanup_error:
            record['cleanup_error'] = repr(cleanup_error)
            raise
        finally:
            if process is not None:
                record['exit_code'] = process.returncode
            record['wall_seconds'] = round(time.monotonic() - start, 6)
            record['finished_at'] = now()
            for name, path in [('stdout', stdout), ('stderr', stderr)]:
                if path.exists():
                    data = path.read_bytes()
                    record[name + '_sha256'] = sha(data)
                    record[name + '_bytes'] = len(data)
            write_json(folder / (label + '.json'), record)
    print(json.dumps({'event': 'finish', 'label': label,
                      'exit_code': record.get('exit_code'),
                      'wall_seconds': record['wall_seconds']}), flush=True)
    if record.get('unexpected_residual_group_after_normal_exit'):
        raise RuntimeError('Command exited with a residual owned process group; cleanup recorded, observation remains invalid')
    return record


def require_success(record):
    assert not record.get('timed_out') and record.get('exit_code') == 0, record

def inventory(record, folder):
    require_success(record)
    rows = (folder / record['stdout']).read_text().splitlines()
    return sorted(row.removesuffix(': test') for row in rows if row.endswith(': test'))
